import numpy as np

def cosec(x):
    return 1/np.sin(x)

def int_dx(A, Wp, Ws, Wi, n):
    if n==0:
        return np.sqrt(np.pi/A)
    
    elif n==2:
        x_2 = -((2 * np.sqrt(np.pi) * (-2 + A * (Wi**2)))/(A**(3/2) * Wi**2))
        return x_2
    
    elif n==4:
        x_4 = (12 * np.sqrt(np.pi) * (-2 + A * Wi**2)**2) / (A**(5/2) * Wi**4)
        return x_4

    elif n==6:
        x_6 = -((120 * np.sqrt(np.pi) * (-2 + A * Wi**2)**3) / (A**(7/2) * Wi**6))
        return x_6

    elif n==8:
        x_8 = (1680 * np.sqrt(np.pi) * (-2 + A * Wi**2)**4) / (A**(9/2) * Wi**8)
        return x_8
    
    elif n==10:
        x_10 = -((30240 * np.sqrt(np.pi) * (-2 + A * Wi**2)**5) / (A**(11/2) * Wi**10))
        return x_10
    
    else:
        return 0

